CREATE TABLE merchant_accounts (merchant_id TEXT PRIMARY KEY, legal_name TEXT NOT NULL, merchant_display_name TEXT NOT NULL, operating_function_id TEXT NOT NULL, processor_id TEXT NOT NULL, processor_name TEXT NOT NULL, processor_account_id TEXT NOT NULL UNIQUE, acquirer_id TEXT NOT NULL, acquirer_name TEXT NOT NULL, account_currency TEXT NOT NULL CHECK (length(account_currency) = 3), country_code TEXT NOT NULL CHECK (length(country_code) = 2), account_status TEXT NOT NULL CHECK (account_status IN ('active','restricted','closed')), created_at TEXT NOT NULL);

CREATE TABLE sales_cohort_ledger (cohort_id TEXT PRIMARY KEY, merchant_id TEXT NOT NULL, processor_id TEXT NOT NULL, sales_date TEXT NOT NULL CHECK (sales_date = date(sales_date)), cohort_scope TEXT NOT NULL CHECK (cohort_scope IN ('completed_sales','processor_dashboard_total','historical_restatement')), is_summary_row INTEGER NOT NULL CHECK (is_summary_row IN (0,1)), payment_method TEXT NOT NULL CHECK (payment_method IN ('card','paypal','apple_pay','google_pay','mixed')), authorization_status TEXT NOT NULL CHECK (authorization_status IN ('authorization_observed','processor_attempt_total','restated')), order_amount_band_lower_cents INTEGER NOT NULL CHECK (order_amount_band_lower_cents >= 0), order_amount_band_upper_cents INTEGER CHECK (order_amount_band_upper_cents IS NULL OR order_amount_band_upper_cents >= order_amount_band_lower_cents), risk_band TEXT NOT NULL CHECK (risk_band IN ('low','medium','high','mixed')), completed_transaction_count INTEGER NOT NULL CHECK (completed_transaction_count >= 0), gross_sales_cents INTEGER NOT NULL CHECK (gross_sales_cents >= 0), source_batch_id TEXT NOT NULL, recorded_at TEXT NOT NULL, FOREIGN KEY (merchant_id) REFERENCES merchant_accounts(merchant_id));

CREATE TABLE issuer_authorization_events (authorization_event_id TEXT PRIMARY KEY, cohort_id TEXT NOT NULL, merchant_id TEXT NOT NULL, processor_id TEXT NOT NULL, event_date TEXT NOT NULL CHECK (event_date = date(event_date)), issuer_name TEXT NOT NULL, issuer_country_code TEXT NOT NULL CHECK (length(issuer_country_code) = 2), merchant_display_name TEXT NOT NULL, response_code TEXT NOT NULL, authorized_transaction_count INTEGER NOT NULL CHECK (authorized_transaction_count >= 0), declined_transaction_count INTEGER NOT NULL CHECK (declined_transaction_count >= 0), authorization_event_count INTEGER NOT NULL CHECK (authorization_event_count = authorized_transaction_count + declined_transaction_count), source_batch_id TEXT NOT NULL, received_at TEXT NOT NULL, FOREIGN KEY (cohort_id) REFERENCES sales_cohort_ledger(cohort_id), FOREIGN KEY (merchant_id) REFERENCES merchant_accounts(merchant_id));